import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"点击劫持","description":"","frontmatter":{"title":"点击劫持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clickjacking.md","filePath":"cs/clickjacking.md","lastUpdated":1789023840000}'),h={name:"cs/clickjacking.md"};function m(_,a,S,u,f,C){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="点击劫持" tabindex="-1">点击劫持 <a class="header-anchor" href="#点击劫持" aria-label="Permalink to &quot;点击劫持&quot;">​</a></h1><div class="epigraph"><p>把目标页嵌进透明框，用户以为在点上层 UI，实际点在下层敏感动作上。防御是不让自己被嵌，或要求额外确认，而不是靠用户看仔细。</p><footer>—— 据 OWASP Clickjacking；RFC 7034 X-Frame-Options；CSP frame-ancestors</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/cors">CORS</a>管读。缺口是<strong>用户的点击被套层</strong>。不需要读响应。本课讲嵌框与防御头，不给钓鱼页制作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>iframe 嵌敏感页，透明度欺骗。X-Frame-Options、CSP frame-ancestors 拒绝嵌。缺口是老浏览器与需要合法嵌入时的精细策略。</p><h3 id="ui-完整性" tabindex="-1">UI 完整性 <a class="header-anchor" href="#ui-完整性" aria-label="Permalink to &quot;UI 完整性&quot;">​</a></h3><p>用户意图与请求错位，类似 CSRF 的视觉亲戚。</p><p><span class="marginnote">OWASP。本课禁止制作点击劫持页面。SameSite 不单独解决嵌框点击。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御头加二次确认敏感动作。下一课 SSRF：服务器被拐去请求内网。</p>',12)),(e(),n(p,null,{default:r(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOP%5B%22%E5%8F%AF%E8%A7%81%20UI%22%5D%20--%3E%20CLICK%5B%22%E7%94%A8%E6%88%B7%E7%82%B9%E5%87%BB%22%5D%0A%20%20HIDDEN%5B%22%E9%80%8F%E6%98%8E%E5%B5%8C%E6%A1%86%22%5D%20--%3E%20CLICK%0A%20%20CLICK%20--%3E%20ACT%5B%22%E6%95%8F%E6%84%9F%E5%8A%A8%E4%BD%9C%E5%9C%A8%E8%A2%AB%E5%B5%8C%E6%BA%90%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>浏览器是用户代理人，也可被视觉混淆。服务器侧敏感操作应假设 UI 可能被套。SSRF 下一课把代理人换成服务器自己。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零制作教程。SSRF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CORS 挡读；点击劫持骗点击。</li><li>frame-ancestors 与 XFO 拒绝被嵌。</li><li>敏感动作二次确认。</li><li>下一课 SSRF。</li><li>出处：RFC 7034；CSP frame-ancestors；OWASP。</li></ul>',8))])}const k=o(h,[["render",m]]);export{A as __pageData,k as default};
